// 📁 src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useState } from "react";
import api from "@/utils/api";

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [admin, setAdmin] = useState(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [loading, setLoading] = useState(true);
  const [initialCheckDone, setInitialCheckDone] = useState(false); // ✅

  // 🔐 Connexion (stocke token + admin + rememberMe)
  const login = (token, user, rememberMe = true) => {
    if (!token || !user) return;
    setIsLoggingIn(true);

    const storage = rememberMe ? localStorage : sessionStorage;
    storage.setItem("adminToken", token);
    storage.setItem("adminUser", JSON.stringify(user));
    setAdmin(user);

    // ✅ Injection immédiate dans axios
    api.defaults.headers.common["Authorization"] = `Bearer ${token}`;

    setTimeout(() => setIsLoggingIn(false), 500);
  };

  // 🔐 Déconnexion
  const logout = () => {
    localStorage.removeItem("adminToken");
    localStorage.removeItem("adminUser");
    sessionStorage.removeItem("adminToken");
    sessionStorage.removeItem("adminUser");
    setAdmin(null);
  };

  // 🔁 Vérification automatique à l'initialisation
  useEffect(() => {
    const token =
      localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");

    console.log("🎯 Token trouvé au démarrage :", token);

    if (!token) {
      setLoading(false);
      setInitialCheckDone(true);
      return;
    }

    // ✅ Injection immédiate du token dans Axios
    api.defaults.headers.common["Authorization"] = `Bearer ${token}`;

    const fetchAdminProfile = async () => {
      try {
        const res = await api.get("/admin/me");
        if (res.data?.admin) {
          setAdmin(res.data.admin);
        } else {
          logout();
        }
      } catch (err) {
        console.error("⛔ Token invalide ou expiré :", err.message);
        logout();
      } finally {
        setLoading(false);
        setInitialCheckDone(true); // ✅ Fin de vérification
      }
    };

    fetchAdminProfile();
  }, []);

  return (
    <AuthContext.Provider
      value={{
        admin,
        login,
        logout,
        isLoggingIn,
        loading,
        initialCheckDone, // ✅ accessible dans AdminLayout
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
